namespace PapayApp.UI.Services;

public sealed record HelpArticle(string Section, string Level, string Title, string Body)
{
    public string Category => $"{Section} · {Level}";
}

public static class HelpCatalog
{
    public const string Guide = "Guía de uso";
    public const string Technical = "Detalles técnicos";
    public const string Problems = "Problemas frecuentes";

    public static IReadOnlyList<HelpArticle> Articles { get; } =
    [
        new("Inicio", Guide, "Empieza y encuentra tus resultados", "La barra lateral abre Inicio, Evaluaciones médicas, Certificados, Resultados de Laboratorio, Archivos y Ajustes. Pasa el cursor sobre un icono para ver su nombre.\n\nDesde Inicio puedes comenzar una evaluación, un certificado o un lote de laboratorio y abrir la carpeta de resultados. Trabajos recientes conserva los últimos 12 lotes registrados y permite abrir sus carpetas; no es una copia de los archivos."),
        new("Evaluaciones médicas", Guide, "Prepara una evaluación médica", "1. Elige Periódica, Preocupacional, Reintegro o Retiro.\n2. Selecciona una empresa y configura la fecha de atención. En Empresa y logotipo puedes registrar una empresa y elegir un logotipo opcional.\n3. Selecciona o arrastra el Excel maestro y elige una hoja compatible.\n4. Revisa las personas, el sexo seleccionado y los avisos. Marca las que deseas incluir y pulsa Generar archivos.\n\nEl resultado de este apartado es un Excel individual (.xlsx) por persona. Usa Abrir carpeta para revisar los archivos generados."),
        new("Evaluaciones médicas", Technical, "Estructura del Excel maestro de evaluaciones", "Usa un archivo .xlsx con columnas de identificación, apellidos y nombres separados. Se reconocen encabezados como Cédula o Identificación, Apellidos y Nombres, aunque cambien de posición, mayúsculas o acentos. También se reconocen Edad, Fecha de nacimiento, Fecha de ingreso, Fecha de retiro, Celular, Centro de costo y Oficio.\n\nUna fila sin identificación se marca como omitida. Si falta el centro de costo se utiliza SIN CENTRO DE COSTO. Revisa los avisos en la lista antes de generar. Este formato es diferente del Excel de Certificados y del de Laboratorio."),
        new("Evaluaciones médicas", Technical, "Carpetas y archivos de las evaluaciones", "La salida se organiza bajo la carpeta base:\nEVALUACION MEDICA - TIPO / Centro de costo / Persona / archivo.xlsx\n\nEl prefijo del archivo identifica el tipo: EV PERIODICA, EV INICIAL, EV REINTEGRO o EV RETIRO. Si el nombre del archivo ya existe, se añade un sufijo para crear otro archivo. Los registros del lote se guardan en la carpeta Logs del tipo de evaluación. El oficio, cuando está informado, se combina con el centro de costo en los campos correspondientes del documento."),
        new("Certificados", Guide, "Genera certificados manuales o desde Excel", "Comprueba la plantilla activa. Elige la captura manual o carga un Excel, completa los datos comunes y los campos adicionales que solicite el diseño. Las firmas utilizan imágenes PNG.\n\nConfigura el último folio utilizado, la fecha y la carpeta de salida. Puedes crear un PDF por persona o un solo PDF con todo el lote. Revisa los datos antes de pulsar Generar certificados. Los campos adicionales se completan una vez para todo el lote; el nombre y la cédula cambian por participante."),
        new("Certificados", Technical, "Excel de certificados: primera hoja y columnas fijas", "La importación usa la primera hoja del archivo .xlsx. La fila 1 contiene encabezados y las personas comienzan en la fila 2.\n\nColumna A: Apellidos y Nombres o Nombre y Apellidos.\nColumna B: Cédula o Número de cédula, con exactamente 10 dígitos.\n\nConserva las cédulas como texto para mantener sus ceros iniciales. Un error en los encabezados o en una fila invalida la importación: corrige el Excel y vuelve a cargarlo. Las cédulas repetidas se avisan, pero en este apartado se genera un certificado por fila."),
        new("Certificados", Technical, "Folios, fechas y archivos PDF", "El folio siguiente es el último utilizado más uno. La app reserva el rango del lote para evitar reutilizar folios si ocurre un fallo; consulta el resumen y el registro para identificar los fallidos. No reduzcas el último folio sin revisar los certificados anteriores.\n\nLos archivos separados usan folio_nombre.pdf; el combinado usa Certificados_inicio-fin.pdf. La variable {fecha} del diseño de certificados utiliza ddMMyyyy. En Laboratorio la fecha dentro del PDF utiliza dd/MM/yyyy. Los certificados se dibujan directamente sobre la plantilla PDF y no requieren Word para generarse."),
        new("Laboratorio", Guide, "Genera los resultados de laboratorio", "1. Selecciona la matriz Excel y una hoja compatible.\n2. Elige la fecha de los informes.\n3. Decide si los toxicológicos serán manuales o automáticos.\n4. Busca y revisa los pacientes; todos los registros válidos se seleccionan al cargar la hoja. Puedes usar Todos o Ninguno.\n5. Pulsa Generar archivos.\n\nLa búsqueda solo filtra la lista visible: no desmarca pacientes. La selección se conserva aunque un paciente quede fuera del filtro. Se guardan dos PDF por paciente. Los serológicos siempre conservan los resultados de la plantilla para revisión manual."),
        new("Laboratorio", Technical, "Cómo se lee el Excel de laboratorio", "Se buscan NOMBRES Y APELLIDOS, CEDULA, EDAD y GENERO en una misma fila entre las primeras 30 filas de cada hoja. Las columnas pueden estar en cualquier orden; se aceptan diferencias de mayúsculas, acentos y espacios. Solo se importa la hoja seleccionada; las hojas no se combinan.\n\nNombre: obligatorio; conserva el orden escrito en el Excel. Cédula: 10 dígitos; si la celda es numérica, se completa con ceros iniciales hasta 10. Edad: entero entre 0 y 120, leído de EDAD, sin calcularlo desde la fecha de nacimiento. Género: M o F, convertido a MASCULINO o FEMENINO. TEST es opcional."),
        new("Laboratorio", Problems, "Se cargan menos pacientes de los esperados", "Revisa Ver avisos de importación. Una fila con nombre, cédula, edad o género inválidos se excluye y el aviso indica la fila del Excel y el dato que debes corregir. Para una cédula repetida solo se conserva la primera fila válida. Las filas sin nombre ni cédula se omiten.\n\nEl conteo se basa en los registros válidos, no en la columna de numeración ni en los totales escritos en otras hojas. Completa o corrige los datos y vuelve a seleccionar el Excel. Un TEST inválido no excluye a la persona: conserva los resultados de la plantilla y produce un aviso al generar en automático."),
        new("Laboratorio", Technical, "Modo manual y lectura automática de TEST", "Manual: completa los datos del paciente y la fecha, y conserva los resultados por defecto de la plantilla.\n\nAutomático: NO REACTIVO escribe Negativo en las siete pruebas. REACTIVO - COC marca cocaína; THC, marihuana; AMP, anfetaminas; BAR, barbitúricos. Se escribe Positivo en las pruebas indicadas y Negativo en las demás. Se aceptan varios códigos, por ejemplo REACTIVO - COC / THC, y repeticiones como THC THC. Solo se resalta en amarillo el texto de la columna RESULTADO.\n\nTEST vacío, TEST INVALIDO, REACTIVO sin código o un código desconocido conservan los resultados por defecto, sin resaltarlos. Se genera igualmente y se registra el aviso. Los serológicos no se completan automáticamente desde las marcas HIV o VDRL del Excel."),
        new("Laboratorio", Technical, "Fecha, nombres y carpetas de los PDF", "La fecha se elige en la app y empieza con el día actual. En los informes se escribe como dd/MM/yyyy, por ejemplo 22/11/2026. La carpeta usa ddMMyyyy, por ejemplo 22112026.\n\nCarpeta base / PRUEBAS / fecha / Nombre del paciente /\nRESULTADO TOXICOLÓGICO EN ORINA -  APELLIDOS NOMBRES.pdf\nRESULTADO SEROLÓGICO DE VIH -  APELLIDOS NOMBRES.pdf\n\nLos nombres de archivo toman el nombre completo del Excel en mayúsculas, conservando su orden. Dos personas con el mismo nombre en el lote se distinguen añadiendo la cédula a sus carpetas. Si los PDF ya existen, se pide confirmación para reemplazarlos. Los dos se convierten antes de guardar el par. Los avisos y errores se registran en la carpeta de la fecha."),
        new("Plantillas", Guide, "Guarda y cambia las plantillas de certificados", "En Ajustes > Configuración > Plantillas de certificados, abre Administrar plantillas. Elige un diseño guardado o usa Nueva plantilla desde PDF, asígnale un nombre y selecciona la página a editar.\n\nLos rectángulos representan las áreas de los componentes. Arrástralos para moverlos y usa sus esquinas para redimensionarlos. El selector de componentes permite elegir elementos superpuestos. Ajusta texto, fuente, tamaño, color y alineación.\n\nSolo Guardar plantilla conserva los cambios y activa ese diseño para generar. Seleccionar otra plantilla abre un borrador; Descarta los cambios para recuperar lo guardado. Cada plantilla conserva su propio diseño."),
        new("Plantillas", Technical, "Textos independientes, firmantes y variables", "Agregar texto crea un dato editable del lote; Agregar texto fijo conserva contenido en la plantilla. Agregar firmante (firma, nombre y cargo) crea tres componentes independientes. Ponles nombres claros: esos nombres serán las etiquetas de los controles en Certificados > Datos adicionales de la plantilla después de guardar.\n\nEl interruptor Solicitar este dato de forma independiente al generar permite que cada componente tenga su propio valor o firma PNG. Variables disponibles: {nombre}, {cedula}, {folio}, {fecha}, {tipo}, {texto}, {firmante} y {cargo}.\n\nLos textos reducen su tamaño para caber en el rectángulo. Si no caben con 6 puntos, se informa un error: amplía el área o reduce el texto, guarda y vuelve a generar."),
        new("Plantillas", Guide, "Cambia las plantillas Word de laboratorio", "En Ajustes > Configuración > Plantillas de laboratorio puedes sustituir por separado el toxicológico y el serológico con un archivo .docx. Prepara en Word los marcadores en los campos correspondientes.\n\nElegir un archivo o Restaurar originales prepara cambios sin aplicarlos. Pulsa Guardar plantillas de laboratorio para activarlos; Descarta los cambios para recuperar las plantillas guardadas. La app conserva copias propias: mover el Word original después de guardar no rompe la plantilla. La salida de generación seguirá siendo PDF."),
        new("Plantillas", Technical, "Marcadores de laboratorio y valores por defecto", "Obligatorios en cada Word: {paciente}, {cedula} y {fecha}. Opcionales, donde existan sus campos: {edad}, {genero} o {sexo}. No se añaden campos nuevos al diseño.\n\nPara toxicológicos automáticos se necesitan los siete marcadores:\n{resultado_anfetaminas|Negativo}\n{resultado_barbituricos|Negativo}\n{resultado_benzodiazepinas|Negativo}\n{resultado_cocaina|Negativo}\n{resultado_marihuana|Negativo}\n{resultado_metadona|Negativo}\n{resultado_morfina|Negativo}\n\nEl texto después de | es el valor por defecto que se conserva en modo manual o con un TEST inválido. Si falta alguno de los siete marcadores, se avisa y se conservan los valores por defecto de toda la plantilla toxicológica. Un marcador desconocido impide guardar la plantilla y el mensaje indica cuál debes corregir."),
        new("Archivos", Guide, "Busca y abre los documentos generados", "Archivos muestra el nombre, tipo y fecha de modificación. Usa la ruta navegable para volver a una carpeta anterior y Subir un nivel para ir a su carpeta superior. La búsqueda se limita a la carpeta actual.\n\nAbrir entra en una subcarpeta o abre un archivo con el programa asociado de Windows. Actualizar vuelve a leer el contenido y Abrir en Windows abre la ubicación en el Explorador. Si moviste archivos desde fuera de la app, actualiza la lista."),
        new("Ajustes", Guide, "Directorio, apariencia y cambios guardados", "Directorio de resultados permite elegir la carpeta base para las evaluaciones y PRUEBAS. Cambiarla afecta a las siguientes generaciones; no traslada los archivos ya creados. Certificados tiene además su propio selector de carpeta de salida.\n\nApariencia permite elegir Claro u Oscuro y texto Normal, Mediano o Grande. La carpeta y la apariencia se guardan al cambiarlas. Los editores de plantillas requieren su botón Guardar.\n\nPuedes cambiar entre Configuración y Ayuda sin aplicar los borradores de las plantillas. La ayuda funciona sin conexión y no modifica los documentos."),
        new("General", Technical, "Requisitos, conversión y datos locales", "PapayApp está preparada para Windows 10 versión 1809 o superior y Windows 11, en x64. El instalador incluye .NET y el prerrequisito Windows App Runtime.\n\nPara exportar Laboratorio a PDF necesitas Microsoft Word instalado o LibreOffice. La app intenta usar Word primero y, si no puede iniciarlo, busca LibreOffice en sus carpetas habituales o en PATH. Abre el programa una vez y completa sus avisos iniciales. Los Word intermedios se crean en una carpeta temporal privada y se eliminan al terminar.\n\nLos Excel de entrada se consultan sin sobrescribirlos. Las empresas, plantillas guardadas e historial reciente se almacenan en los datos locales de la app; la carpeta base, apariencia y folio se conservan como preferencias. Los archivos generados se guardan en las carpetas de salida elegidas."),
        new("General", Problems, "No aparece una hoja de Excel o no carga el archivo", "Comprueba que el archivo sea .xlsx y que Windows pueda abrirlo. Si está en una unidad externa o carpeta de red, confirma que esté disponible.\n\nLaboratorio: los cuatro encabezados obligatorios deben estar juntos en una fila entre las primeras 30. GENERO debe contener M o F.\nEvaluaciones: utiliza identificación y nombres y apellidos en columnas separadas, con encabezados reconocidos.\nCertificados: primera hoja, encabezados en fila 1, nombre en A y cédula de 10 dígitos en B.\n\nGuarda las correcciones en Excel y vuelve a cargar el archivo en PapayApp. Cambiarlo fuera de la app no actualiza por sí solo la lista importada."),
        new("General", Problems, "No se puede guardar, convertir o abrir un resultado", "Si aparece archivo en uso, cierra el PDF, Word o Excel correspondiente y vuelve a intentarlo. Si falta permiso, elige una carpeta con acceso de escritura en Ajustes o en la salida de Certificados. Comprueba espacio libre y conexión a la unidad.\n\nSi Laboratorio no convierte a PDF, verifica Word o LibreOffice, abre allí la plantilla y comprueba que no tenga avisos pendientes. Si falta un marcador, corrige el Word y guarda de nuevo la plantilla desde Ajustes. Si no puedes abrir un PDF ya creado, comprueba que Windows tenga una aplicación asociada para PDF.\n\nConsulta el resumen del lote: Abrir PDF o Abrir archivo muestra el primero; Abrir carpeta permite revisar todos; Ver errores abre el registro cuando existe; Generar otro lote prepara una nueva entrada. Si el problema continúa, conserva el mensaje completo, la versión de la app y la fila indicada para solicitar ayuda.")
    ];
}
